INSERT INTO community_users (id, nickname, avatar_prompt, bio, accent_color) VALUES
(1, '云舒', 'Editorial portrait of a young Chinese woman, soft daylight, short black hair, calm expression, white studio background, modern creative professional, natural skin texture, centered headshot, premium magazine photography, no text', '把日常折成一页灵感。', '#E85D3F'),
(2, '星野', 'Editorial portrait of a young Chinese man, warm window light, textured black hair, thoughtful expression, pale blue studio background, modern designer, natural skin texture, centered headshot, premium magazine photography, no text', '收集城市里微小的光。', '#2F6FED'),
(3, '砚青', 'Editorial portrait of a young Chinese woman, long dark hair tied loosely, confident gentle expression, sage green studio background, contemporary artist, natural skin texture, centered headshot, premium magazine photography, no text', '在留白里安放想象。', '#2C8C72'),
(4, '苏禾', 'Editorial portrait of a young Chinese man, clean short haircut, subtle smile, coral studio background, architecture student, natural skin texture, centered headshot, premium magazine photography, no text', '慢一点，看见更多。', '#E79B34'),
(5, '林渡', 'Editorial portrait of a young Chinese woman, wavy shoulder length hair, direct gaze, soft lilac gray studio background, independent photographer, natural skin texture, centered headshot, premium magazine photography, no text', '正在经过，也正在记录。', '#8D62C9'),
(6, '月白', 'Editorial portrait of a young Chinese man, medium length dark hair, serene expression, warm ivory studio background, ceramic artist, natural skin texture, centered headshot, premium magazine photography, no text', '愿每次表达都轻盈。', '#D46A82'),
(7, '南栀', 'Editorial portrait of a young Chinese woman, neat bob haircut, bright composed expression, mustard yellow studio background, product designer, natural skin texture, centered headshot, premium magazine photography, no text', '为普通事物重新命名。', '#C99219'),
(8, '清和', 'Editorial portrait of a young Chinese man, round glasses, relaxed smile, mint gray studio background, digital illustrator, natural skin texture, centered headshot, premium magazine photography, no text', '让复杂的世界简单一点。', '#3A8F8A'),
(9, '朝雾', 'Editorial portrait of a young Chinese woman, wispy fringe, quiet cinematic expression, light rose studio background, filmmaker, natural skin texture, centered headshot, premium magazine photography, no text', '清晨适合重新出发。', '#C95A72'),
(10, '知夏', 'Editorial portrait of a young Chinese man, slightly tousled hair, open friendly expression, sky blue studio background, visual artist, natural skin texture, centered headshot, premium magazine photography, no text', '灵感不设边界。', '#337FB5');
INSERT INTO image_assets (id, title, image_prompt, alt_text, accent_color, sort_order) VALUES
(1, '雾岛', 'Aerial photograph of a tiny green island emerging through silver morning fog, quiet blue sea, minimalist composition, crisp natural details, contemporary travel editorial, no people, no text', '银色晨雾中的绿色小岛', '#73959A', 1),
(2, '橙椅', 'Single sculptural orange chair in a sunlit brutalist concrete room, long geometric shadows, high end interior editorial photography, clean composition, no text', '混凝土空间中的橙色椅子', '#E76C3C', 2),
(3, '潮汐', 'Close aerial view of turquoise ocean waves folding over pale sand, graphic natural patterns, luminous water, fine art photography, no people, no text', '青绿色海浪与浅色沙滩', '#278F9B', 3),
(4, '纸境', 'Architectural paper sculpture in white and vermilion, folded planes and circular cutouts, soft directional studio light, modern design still life, no text', '白色与朱红色纸艺建筑', '#D9573F', 4),
(5, '夜站', 'Quiet modern train platform at blue hour, one glowing red sign without lettering, wet reflective floor, cinematic urban photography, no visible faces, no text', '蓝调时刻的安静站台', '#355A7A', 5),
(6, '青苔', 'Macro photograph of vivid green moss covering weathered volcanic stone, tiny dew drops, rich tactile detail, soft overcast light, no text', '带露珠的青苔与火山石', '#3D7753', 6),
(7, '夏窗', 'Open window with sheer white curtain moving in a summer breeze, blue sky and one lemon on the sill, bright quiet film photography, no text', '夏日窗边的白纱与柠檬', '#E7B83E', 7),
(8, '赤丘', 'Surreal red clay hills under a pale cyan sky, a narrow white path crossing the landscape, clean editorial landscape photograph, no people, no text', '红色丘陵与白色小路', '#C24F3C', 8),
(9, '玻璃', 'Transparent colored glass objects casting overlapping cyan amber and rose shadows on white paper, refined studio still life, sharp sunlight, no text', '彩色玻璃投下透明光影', '#D18D4A', 9),
(10, '海报墙', 'Contemporary gallery wall covered in abstract monochrome posters with shapes only and no lettering, warm museum light, editorial interior photography, no readable text', '抽象图形组成的画廊海报墙', '#33383F', 10),
(11, '风塔', 'Minimal white wind turbines across rolling emerald fields beneath dramatic clean clouds, wide cinematic landscape, sustainable future mood, no text', '绿色山野间的白色风机', '#5D9364', 11),
(12, '蓝瓶', 'Cobalt blue ceramic bottles arranged on a stainless steel table, hard midday sunlight, graphic shadows, luxury product still life, no labels, no text', '不锈钢台面上的钴蓝陶瓶', '#3159A8', 12),
(13, '雨巷', 'Narrow East Asian city alley after rain, soft peach storefront glow, bicycles and reflections, intimate cinematic photography, no visible logos, no text', '雨后小巷与暖色灯光', '#A55C55', 13),
(14, '云梯', 'A white staircase rising into dense sunlit clouds, dreamlike but photorealistic, minimal surreal architecture, soft pearl tones, no people, no text', '伸向云层的白色阶梯', '#AABBC5', 14),
(15, '花市', 'Buckets of ranunculus and wildflowers at an outdoor flower market, rich coral yellow and magenta color, candid editorial photography, no faces, no text', '花市里缤纷的鲜花桶', '#D86863', 15),
(16, '石室', 'Monumental stone room with a circular skylight and a single shallow reflecting pool, serene contemporary architecture, soft daylight, no people, no text', '圆形天窗下的石室与水池', '#8D887D', 16),
(17, '飞鸟', 'Flock of white birds crossing a deep ultramarine sky above a thin horizon line, minimalist nature photography, graceful spacing, no text', '群鸟飞过深蓝天空', '#2656A4', 17),
(18, '果盘', 'Chrome fruit bowl with pears and blood oranges on a vivid red table, playful modern food editorial, direct flash, crisp detail, no text', '红色桌面上的金属果盘', '#CE4939', 18),
(19, '冰川', 'Close view of translucent blue glacial ice with dark mineral lines, abstract natural geometry, cold clear daylight, fine art photography, no text', '蓝色冰川中的天然纹理', '#4386A5', 19),
(20, '路灯', 'One yellow street lamp glowing in a snowy minimalist landscape at dusk, pale lavender sky, quiet cinematic photograph, no people, no text', '雪原暮色中的黄色路灯', '#D6A52A', 20),
(21, '木构', 'Interlocking timber architectural structure viewed from below, warm cedar beams against clear sky, precise geometry, contemporary architecture photography, no text', '仰视交错的木质建筑结构', '#A86F40', 21),
(22, '泳池', 'Geometric outdoor swimming pool in saturated aqua with a single vermilion diving platform, overhead sunlight, modern resort editorial, no people, no text', '水蓝泳池与朱红跳台', '#20A2AD', 22),
(23, '山屋', 'Tiny modern cabin with warm windows beneath a huge snowy mountain at twilight, wide cinematic landscape, crisp air, no people, no text', '雪山脚下亮灯的小屋', '#596B7C', 23),
(24, '茶席', 'Minimal tea setting with handmade gray ceramics and one green branch on dark charcoal linen, soft side light, Japanese inspired editorial still life, no text', '深色亚麻布上的手作茶器', '#65695D', 24),
(25, '霓虹', 'Abstract close photograph of red and cyan neon reflected in curved brushed metal, futuristic texture, deep contrast, no logos, no text', '红蓝霓虹映在弧形金属上', '#B74752', 25),
(26, '麦浪', 'Golden wheat field moving in strong wind under a vast storm blue sky, tactile cinematic landscape photography, low horizon, no people, no text', '风中麦浪与暴雨前的蓝天', '#C69B3B', 26),
(27, '书桌', 'Creative desk with sketchbook, black fountain pen, red ruler and small stone, morning sun, organized editorial workspace, no brand marks, no readable text', '晨光中的创意工作桌', '#BB5545', 27),
(28, '礁石', 'Black volcanic rocks in milky long exposure ocean water, pale peach sunrise, meditative fine art seascape, no people, no text', '晨光中海水环绕黑色礁石', '#776D72', 28),
(29, '拱廊', 'Series of terracotta arches and cobalt blue shadows in a modern courtyard, bold Mediterranean architecture photography, no people, no text', '陶土色拱廊与钴蓝阴影', '#B86448', 29),
(30, '绿屋', 'Small greenhouse overflowing with tropical green plants, transparent glass and morning mist, lush but clean editorial photography, no people, no text', '晨雾中的玻璃绿植房', '#43805E', 30),
(31, '月面', 'Detailed moon surface rendered as a quiet pale gray landscape with one small mirrored sphere, photorealistic surreal art, deep black sky, no text', '月面上的一颗镜面球', '#97999D', 31),
(32, '红门', 'Bright red door in a smooth pale pink wall, one sharp diagonal shadow, minimalist architectural photography, centered composition, no text', '粉色墙面上的鲜红门扉', '#D9473C', 32),
(33, '蓝桥', 'Elegant blue pedestrian bridge curving across calm silver water in morning haze, contemporary infrastructure photography, no people, no text', '晨雾水面上的蓝色步行桥', '#477FA0', 33),
(34, '光盒', 'Luminous translucent cube standing in a dark empty gallery, subtle rainbow refractions on concrete floor, immersive installation photography, no people, no text', '暗色展厅中的发光透明方盒', '#7B71A8', 34),
(35, '柿树', 'Single persimmon tree with bright orange fruit in an open pale field, late autumn fog, poetic editorial landscape, no people, no text', '薄雾原野里挂满果实的柿树', '#CB7136', 35),
(36, '曲线', 'Close crop of a white spiral staircase with a cobalt blue handrail, graphic curves and clean sunlight, architecture editorial, no people, no text', '白色旋梯与钴蓝扶手', '#3268A5', 36),
(37, '石榴', 'Open pomegranate and scattered ruby seeds on a brushed steel surface, dramatic side light, modern food still life, no text', '金属台面上的石榴与籽', '#A92F3D', 37),
(38, '浮云', 'Large soft cloud reflected perfectly in a still salt lake, nearly white horizon and tiny coral marker, dreamlike minimalist photography, no text', '盐湖倒映着一朵巨大白云', '#89AFC0', 38),
(39, '铅字', 'Vintage metal letterpress blocks arranged as abstract texture with all characters turned away and unreadable, warm raking light, tactile photography, no readable text', '暖光中的复古金属铅字纹理', '#806B56', 39),
(40, '晨跑', 'Distant runner in a bright cobalt outfit crossing a wide pale concrete plaza at sunrise, long shadow, minimalist urban sports photography, no logos, no text', '晨光广场上远处的奔跑者', '#366EB2', 40);
INSERT INTO projects (id, user_id, image_asset_id, name, description, created_at) VALUES
(1, 1, 1, '雾中岛', '从海面醒来的那一刻开始，留白也有了方向。', TIMESTAMPADD(HOUR, -2, CURRENT_TIMESTAMP(3))),
(2, 2, 2, '橙色椅', '一把椅子，也可以决定整个空间的情绪。', TIMESTAMPADD(HOUR, -5, CURRENT_TIMESTAMP(3))),
(3, 3, 4, '折光册', '纸张、光线和建筑感的一次小实验。', TIMESTAMPADD(HOUR, -9, CURRENT_TIMESTAMP(3))),
(4, 4, 7, '夏日窗', '风穿过窗帘时，房间有了自己的呼吸。', TIMESTAMPADD(DAY, -1, CURRENT_TIMESTAMP(3))),
(5, 5, 13, '雨后巷', '雨停以后，城市把灯光留在了地面。', TIMESTAMPADD(DAY, -1, TIMESTAMPADD(HOUR, -3, CURRENT_TIMESTAMP(3)))),
(6, 6, 16, '静水室', '我喜欢空间里没有明确答案的时刻。', TIMESTAMPADD(DAY, -2, CURRENT_TIMESTAMP(3))),
(7, 7, 18, '红果盘', '给日常物件一点直接、明亮的颜色。', TIMESTAMPADD(DAY, -2, TIMESTAMPADD(HOUR, -6, CURRENT_TIMESTAMP(3)))),
(8, 8, 22, '碧水台', '几何和盛夏，都是简单但有效的快乐。', TIMESTAMPADD(DAY, -3, CURRENT_TIMESTAMP(3))),
(9, 9, 25, '夜之光', '反射让确定的边界变得柔软。', TIMESTAMPADD(DAY, -4, CURRENT_TIMESTAMP(3))),
(10, 10, 29, '拱影间', '旅行中记下的一组颜色关系。', TIMESTAMPADD(DAY, -5, CURRENT_TIMESTAMP(3))),
(11, 1, 35, '秋柿原', '有些颜色只在秋天出现一次。', TIMESTAMPADD(DAY, -6, CURRENT_TIMESTAMP(3))),
(12, 3, 31, '月面球', '熟悉的形状放在陌生环境里，就有了故事。', TIMESTAMPADD(DAY, -7, CURRENT_TIMESTAMP(3))),
(13, 5, 38, '云之镜', '水面把天空重新讲了一遍。', TIMESTAMPADD(DAY, -8, CURRENT_TIMESTAMP(3))),
(14, 7, 30, '绿房子', '透明边界里的旺盛生命力。', TIMESTAMPADD(DAY, -9, CURRENT_TIMESTAMP(3))),
(15, 9, 33, '蓝桥弯', '一条线跨过水面，也连接了清晨。', TIMESTAMPADD(DAY, -10, CURRENT_TIMESTAMP(3))),
(16, 10, 40, '晨光跑', '城市还没完全醒来，身体已经先出发。', TIMESTAMPADD(DAY, -11, CURRENT_TIMESTAMP(3)));
