INSERT INTO project_comments (project_id, user_id, content, created_at) VALUES
(1, 3, '这个雾的层次太舒服了，像一段很轻的开场。', TIMESTAMPADD(MINUTE, -90, CURRENT_TIMESTAMP(3))),
(1, 8, '留白和小岛的比例刚刚好。', TIMESTAMPADD(MINUTE, -64, CURRENT_TIMESTAMP(3))),
(2, 7, '橙色一下把空间点亮了。', TIMESTAMPADD(HOUR, -3, CURRENT_TIMESTAMP(3))),
(3, 1, '纸张的边缘光很漂亮。', TIMESTAMPADD(HOUR, -6, CURRENT_TIMESTAMP(3))),
(3, 10, '想看到这组实验的下一张。', TIMESTAMPADD(HOUR, -4, CURRENT_TIMESTAMP(3))),
(4, 2, '已经听到风吹窗帘的声音了。', TIMESTAMPADD(HOUR, -18, CURRENT_TIMESTAMP(3))),
(5, 6, '雨后的反光是城市最温柔的滤镜。', TIMESTAMPADD(DAY, -1, CURRENT_TIMESTAMP(3))),
(7, 9, '直接又有生命力，喜欢这组配色。', TIMESTAMPADD(DAY, -2, CURRENT_TIMESTAMP(3))),
(8, 10, '夏天就应该是这种蓝。', TIMESTAMPADD(DAY, -2, CURRENT_TIMESTAMP(3))),
(10, 3, '陶土色和蓝色的关系很耐看。', TIMESTAMPADD(DAY, -4, CURRENT_TIMESTAMP(3))),
(12, 7, '镜面球让画面突然有了尺度感。', TIMESTAMPADD(DAY, -6, CURRENT_TIMESTAMP(3))),
(13, 1, '安静得像时间暂停了一样。', TIMESTAMPADD(DAY, -7, CURRENT_TIMESTAMP(3)));
